SELECT eb.bin_id, eb.event_count, eb.non_event_count
FROM event_bins eb
ORDER BY eb.bin_id;

SELECT SUM(julianday(contributions.updated_at) - julianday(contributions.created_at)) AS cumulative_total_changes 
FROM contributions 
JOIN contributors ON contributions.contributor_id = contributors.contributor_id;

SELECT station_id, AVG(co_mean) OVER (PARTITION BY station_id ORDER BY measure_date) AS cumulative_avg_co
FROM air_quality_data
ORDER BY station_id;
